use Illuminate\Database\Console\Seeds\WithoutModelEvents;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;

/**
 * Seed data equipment kategori Body Shop (BD).
 * Total 666 baris. Termasuk kolom 'machine_category' (hasil heuristik
 * strip suffix dari equipment_name, misal 'Air Hoist Front Body ST#1' ->
 * kategori 'Air Hoist Front Body') -- review lagi kalau ada yang kurang pas,
 * tinggal edit array $this->rows() di bawah lalu re-run (aman, insertOrIgnore).
 *
 * PENTING: kalau mengubah machine_category SETELAH data ini ke-insert ke DB,
 * insertOrIgnore() tidak akan meng-update baris yang sudah ada (equipment_code
 * sama = di-skip). Untuk update category baris existing, pakai UPDATE manual
 * atau lewat form Edit equipment, bukan re-run seeder ini.
 *
 * Rollback: (new \Database\Seeders\BodyShopEquipmentSeeder)->rollback();
 */
class BodyShopEquipmentSeeder extends Seeder
{
    use WithoutModelEvents;

    public function run(): void
    {
        $now = now();
        $rows = collect($this->rows())->map(function ($row) use ($now) {
            return array_merge($row, [
                'tis_number' => null,
                'etm_group' => 'Body Shop',
                'location' => null,
                'status' => 'active',
                'specifications' => null,
                'created_at' => $now,
                'updated_at' => $now,
            ]);
        });

        $rows->chunk(200)->each(function ($chunk) {
            DB::table('equipment')->insertOrIgnore($chunk->toArray());
        });

        $this->command?->info('BodyShopEquipmentSeeder: ' . $rows->count() . ' baris diproses.');
    }

    public function rollback(): int
    {
        $codes = collect($this->rows())->pluck('equipment_code')->all();
        return DB::table('equipment')->whereIn('equipment_code', $codes)->delete();
    }

